// authTransport injects whatever credentials are present on the config onto
// each outgoing request. Centralising this in one RoundTripper means a single
// audit point for credential handling and prevents accidental credential
// leakage into application logs or metrics.
//
// The generator emits per-operation context.WithValue plumbing for each
// security scheme; we bypass that entirely. Endpoints that need a specific
// scheme will succeed as long as the corresponding option was set at NewClient.
type authTransport struct {
	cfg  *config
	base http.RoundTripper
}

func newAuthTransport(cfg *config, base http.RoundTripper) *authTransport {
	if base == nil {
		base = http.DefaultTransport
	}
	return &authTransport{cfg: cfg, base: base}
}

