	// credentials, User-Agent, signing — overwrites them. A default header can
	// never mask a credential.
	for k, v := range t.cfg.defaultHeaders {
		req.Header.Set(k, v)
	}

	if t.cfg.userAgent != "" {
		req.Header.Set("User-Agent", t.cfg.userAgent)
	}

	// Cross-cutting header options, applied to every request.
	if t.cfg.originIP != "" {
		req.Header.Set("X-Origin-IP", t.cfg.originIP)
	}
	if t.cfg.preventWebhook {
		req.Header.Set("X-PreventWebhook", "true")
	}

	// Header credentials. Sending via header keeps the credential out of
	// access logs, browser history, and proxy URL caches, so it is always
	// preferred where the API accepts it. Where a dedicated override option
	// exists it wins, letting callers send a different value on the header
	// than on the query (e.g. an internal gateway that rewrites one only).
	if v := firstNonEmpty(t.cfg.xLoginRadiusAPIKey, t.cfg.apiKey); v != "" {
		req.Header.Set("X-LoginRadius-ApiKey", v)
	}
	if v := firstNonEmpty(t.cfg.xLoginRadiusAPISecret, t.cfg.apiSecret); v != "" {
		req.Header.Set("X-LoginRadius-ApiSecret", v)
	}

	// Authorization: Bearer — the candidates below share one header, so the
	// first one set wins (manifest declares the precedence).
	switch {
	case t.cfg.bearerToken != "":
		req.Header.Set("Authorization", "Bearer "+t.cfg.bearerToken)
	case t.cfg.m2mBearerToken != "":
		req.Header.Set("Authorization", "Bearer "+t.cfg.m2mBearerToken)
	}

	// Query-string credentials. The LoginRadius spec declares operations that
	// accept ONLY the query schemes, so these are always populated as a
	// fallback; endpoints that accept a header scheme use it regardless.
	//
	// We append only when the caller did not already set the key — this
	// preserves any per-call overrides made through the generated fluent API.
	q := req.URL.Query()
