	setIfAbsent("apisecret", t.cfg.apiSecret)
	setIfAbsent("client_id", t.cfg.clientID)
	setIfAbsent("client_secret", t.cfg.clientSecret)
	setIfAbsent("access_token", t.cfg.accessToken)
	setIfAbsent("region", t.cfg.serverRegion)
	setIfAbsent("fields", t.cfg.fields)
