// stripSigningQuery removes the secret parameter from a request's URL in
// place, so it is neither signed nor sent.
func stripSigningQuery(req *http.Request) {
	q := req.URL.Query()
	if !q.Has(signingStripParam) {
		return
	}
	q.Del(signingStripParam)
	req.URL.RawQuery = q.Encode()
}

// redactedHeaders are logged by NAME only. Writing a tenant secret to a log
// would be a disclosure, so their values never reach the writer.
var redactedHeaders = map[string]bool{
	"x-loginradius-apikey":    true,
	"x-loginradius-apisecret": true,
	"authorization":           true,
	"digest":                  true,
}

// logRequest writes a one-line summary of the outgoing request.
func (t *authTransport) logRequest(req *http.Request) {
	if t.cfg.debug == nil {
		return
	}
	// Query VALUES can carry credentials, so only the keys are listed.
	keys := make([]string, 0, len(req.URL.Query()))
	for k := range req.URL.Query() {
		keys = append(keys, k)
	}
	names := make([]string, 0, len(req.Header))
	for name := range req.Header {
		if redactedHeaders[lowerASCII(name)] {
			names = append(names, name+"=[REDACTED]")
			continue
		}
		names = append(names, name+"="+req.Header.Get(name))
	}
	fmt.Fprintf(t.cfg.debug, "loginradius: %s %s%s query=%v headers=%v\n",
		req.Method, req.URL.Host, req.URL.Path, keys, names)
}

// lowerASCII lower-cases an ASCII header name without going through the
// unicode tables.
func lowerASCII(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func firstNonEmpty(a, b string) string {
	if a != "" {
		return a
	}
	return b
}
